import{C as Fu,Gn as rw,U as Lb,d as Bg,f as Bi}from"./chunk-BlRON4FE.js";import{s as _r}from"./main-NELXZSUR.js";import{t as x}from"./chunk-k6GCvH-T.js";var d=class u{static ɵfac=function(r){return new(r||u)};static ɵcmp=rw({type:u,selectors:[[`app-privacy-page`]],decls:138,vars:0,consts:[[`headline`,`Datenschutzerklärung`],[1,`index`,`index--list`,`mt-n5`],[1,`index__stripe`,`index__stripe--list`],[1,`container`],[1,`row`],[1,`col-12`],[1,`index__item`,`index__item--list`,`mb-5`],[`routerLink`,`/impressum`],[`href`,`https://www.google.de/intl/de/policies/privacy`,`target`,`_blank`]],template:function(r,h){r&1&&(Bg(0,`app-hero-header`,0),Bi(1,`section`,1)(2,`div`,2)(3,`div`,3)(4,`div`,4)(5,`div`,5)(6,`div`,6)(7,`h2`),Lb(8,`1. Datenschutz auf einen Blick`),Fu(),Bi(9,`h3`),Lb(10,`Allgemeine Hinweise`),Fu(),Bi(11,`p`),Lb(12,`Die folgenden Hinweise geben einen einfachen Überblick darüber, was mit Ihren personenbezogenen Daten passiert, wenn Sie unsere Website besuchen. Personenbezogene Daten sind alle Daten, mit denen Sie persönlich identifiziert werden können. Ausführliche Informationen zum Thema Datenschutz entnehmen Sie unserer unter diesem Text aufgeführten Datenschutzerklärung.`),Fu(),Bi(13,`h3`),Lb(14,`Datenerfassung auf unserer Website`),Fu(),Bi(15,`p`)(16,`strong`),Lb(17,`Wer ist verantwortlich für die Datenerfassung auf dieser Website?`),Fu()(),Bi(18,`p`),Lb(19,`Die Datenverarbeitung auf dieser Website erfolgt durch den Websitebetreiber. Dessen Kontaktdaten können Sie dem `),Bi(20,`a`,7),Lb(21,`Impressum`),Fu(),Lb(22,` dieser Website entnehmen.`),Fu(),Bi(23,`p`)(24,`strong`),Lb(25,`Wie erfassen wir Ihre Daten?`),Fu()(),Bi(26,`p`),Lb(27,`Ihre Daten werden zum einen dadurch erhoben, dass Sie uns diese mitteilen. Hierbei kann es sich z.B. um Daten handeln, die Sie in ein Kontaktformular eingeben.`),Fu(),Bi(28,`p`),Lb(29,`Andere Daten werden automatisch beim Besuch der Website durch unsere IT-Systeme erfasst. Das sind vor allem technische Daten (z.B. Internetbrowser, Betriebssystem oder Uhrzeit des Seitenaufrufs). Die Erfassung dieser Daten erfolgt automatisch, sobald Sie unsere Website betreten.`),Fu(),Bi(30,`p`)(31,`strong`),Lb(32,`Wofür nutzen wir Ihre Daten?`),Fu()(),Bi(33,`p`),Lb(34,`Ein Teil der Daten wird erhoben, um eine fehlerfreie Bereitstellung der Website zu gewährleisten. Andere Daten können zur Analyse Ihres Nutzerverhaltens verwendet werden.`),Fu(),Bi(35,`p`)(36,`strong`),Lb(37,`Welche Rechte haben Sie bezüglich Ihrer Daten?`),Fu()(),Bi(38,`p`),Lb(39,`Sie haben jederzeit das Recht unentgeltlich Auskunft über Herkunft, Empfänger und Zweck Ihrer gespeicherten personenbezogenen Daten zu erhalten. Sie haben außerdem ein Recht, die Berichtigung, Sperrung oder Löschung dieser Daten zu verlangen. Hierzu sowie zu weiteren Fragen zum Thema Datenschutz können Sie sich jederzeit unter der im Impressum angegebenen Adresse an uns wenden. Des Weiteren steht Ihnen ein Beschwerderecht bei der zuständigen Aufsichtsbehörde zu.`),Fu(),Bi(40,`h3`),Lb(41,`Analyse-Tools und Tools von Drittanbietern`),Fu(),Bi(42,`p`),Lb(43,`Beim Besuch unserer Website kann Ihr Surf-Verhalten statistisch ausgewertet werden. Das geschieht vor allem mit Cookies und mit sogenannten Analyseprogrammen. Die Analyse Ihres Surf-Verhaltens erfolgt in der Regel anonym; das Surf-Verhalten kann nicht zu Ihnen zurückverfolgt werden. Sie können dieser Analyse widersprechen oder sie durch die Nichtbenutzung bestimmter Tools verhindern. Detaillierte Informationen dazu finden Sie in der folgenden Datenschutzerklärung.`),Fu(),Bi(44,`p`),Lb(45,`Sie können dieser Analyse widersprechen. Über die Widerspruchsmöglichkeiten werden wir Sie in dieser Datenschutzerklärung informieren.`),Fu(),Bi(46,`h2`),Lb(47,`2. Allgemeine Hinweise und Pflichtinformationen`),Fu(),Bi(48,`h3`),Lb(49,`Datenschutz`),Fu(),Bi(50,`p`),Lb(51,`Die Betreiber dieser Seiten nehmen den Schutz Ihrer persönlichen Daten sehr ernst. Wir behandeln Ihre personenbezogenen Daten vertraulich und entsprechend der gesetzlichen Datenschutzvorschriften sowie dieser Datenschutzerklärung.`),Fu(),Bi(52,`p`),Lb(53,`Wenn Sie diese Website benutzen, werden verschiedene personenbezogene Daten erhoben. Personenbezogene Daten sind Daten, mit denen Sie persönlich identifiziert werden können. Die vorliegende Datenschutzerklärung erläutert, welche Daten wir erheben und wofür wir sie nutzen. Sie erläutert auch, wie und zu welchem Zweck das geschieht.`),Fu(),Bi(54,`p`),Lb(55,`Wir weisen darauf hin, dass die Datenübertragung im Internet (z.B. bei der Kommunikation per E-Mail) Sicherheitslücken aufweisen kann. Ein lückenloser Schutz der Daten vor dem Zugriff durch Dritte ist nicht möglich.`),Fu(),Bi(56,`h3`),Lb(57,`Hinweis zur verantwortlichen Stelle`),Fu(),Bi(58,`p`),Lb(59,`Die verantwortliche Stelle für die Datenverarbeitung auf dieser Website ist:`),Fu(),Bi(60,`p`),Lb(61,` Johannes Hoppe `),Bg(62,`br`),Lb(63,` Feilgasse 5F `),Bg(64,`br`),Lb(65,` 69181 Leimen`),Fu(),Bi(66,`p`),Lb(67,`Telefon: 015168122266 `),Bg(68,`br`),Lb(69,` E-Mail: johannes.hoppe@haushoppe-its.de`),Fu(),Bi(70,`p`),Lb(71,`Verantwortliche Stelle ist die natürliche oder juristische Person, die allein oder gemeinsam mit anderen über die Zwecke und Mittel der Verarbeitung von personenbezogenen Daten (z.B. Namen, E-Mail-Adressen o. Ä.) entscheidet.`),Fu(),Bi(72,`h3`),Lb(73,`Widerruf Ihrer Einwilligung zur Datenverarbeitung`),Fu(),Bi(74,`p`),Lb(75,`Viele Datenverarbeitungsvorgänge sind nur mit Ihrer ausdrücklichen Einwilligung möglich. Sie können eine bereits erteilte Einwilligung jederzeit widerrufen. Dazu reicht eine formlose Mitteilung per E-Mail an uns. Die Rechtmäßigkeit der bis zum Widerruf erfolgten Datenverarbeitung bleibt vom Widerruf unberührt.`),Fu(),Bi(76,`h3`),Lb(77,`SSL- bzw. TLS-Verschlüsselung`),Fu(),Bi(78,`p`),Lb(79,`Diese Seite nutzt aus Sicherheitsgründen und zum Schutz der Übertragung vertraulicher Inhalte, wie zum Beispiel Bestellungen oder Anfragen, die Sie an uns als Seitenbetreiber senden, eine SSL-bzw. TLS-Verschlüsselung. Eine verschlüsselte Verbindung erkennen Sie daran, dass die Adresszeile des Browsers von “http://” auf “https://” wechselt und an dem Schloss-Symbol in Ihrer Browserzeile.`),Fu(),Bi(80,`p`),Lb(81,`Wenn die SSL- bzw. TLS-Verschlüsselung aktiviert ist, können die Daten, die Sie an uns übermitteln, nicht von Dritten mitgelesen werden.`),Fu(),Bi(82,`h3`),Lb(83,`Auskunft, Sperrung, Löschung`),Fu(),Bi(84,`p`),Lb(85,`Sie haben im Rahmen der geltenden gesetzlichen Bestimmungen jederzeit das Recht auf unentgeltliche Auskunft über Ihre gespeicherten personenbezogenen Daten, deren Herkunft und Empfänger und den Zweck der Datenverarbeitung und ggf. ein Recht auf Berichtigung, Sperrung oder Löschung dieser Daten. Hierzu sowie zu weiteren Fragen zum Thema personenbezogene Daten können Sie sich jederzeit unter der im Impressum angegebenen Adresse an uns wenden.`),Fu(),Bi(86,`h2`),Lb(87,`3. Datenerfassung auf unserer Website`),Fu(),Bi(88,`h3`),Lb(89,`Cookies`),Fu(),Bi(90,`p`),Lb(91,`Wir setzen auf dieser Website keine Cookies ein.`),Fu(),Bi(92,`h3`),Lb(93,`Server-Log-Dateien`),Fu(),Bi(94,`p`),Lb(95,`Der Provider der Seiten erhebt und speichert automatisch Informationen in so genannten Server-Log-Dateien, die Ihr Browser automatisch an uns übermittelt. Dies sind:`),Fu(),Bi(96,`ul`)(97,`li`),Lb(98,`Browsertyp und Browserversion`),Fu(),Bi(99,`li`),Lb(100,`verwendetes Betriebssystem`),Fu(),Bi(101,`li`),Lb(102,`Referrer URL`),Fu(),Bi(103,`li`),Lb(104,`Hostname des zugreifenden Rechners`),Fu(),Bi(105,`li`),Lb(106,`Uhrzeit der Serveranfrage`),Fu(),Bi(107,`li`),Lb(108,`IP-Adresse`),Fu()(),Bi(109,`p`),Lb(110,`Eine Zusammenführung dieser Daten mit anderen Datenquellen wird nicht vorgenommen.`),Fu(),Bi(111,`p`),Lb(112,`Grundlage für die Datenverarbeitung ist Art. 6 Abs. 1 lit. f DSGVO, der die Verarbeitung von Daten zur Erfüllung eines Vertrags oder vorvertraglicher Maßnahmen gestattet.`),Fu(),Bi(113,`h3`),Lb(114,`Kontaktformular`),Fu(),Bi(115,`p`),Lb(116,`Wenn Sie uns per Kontaktformular Anfragen zukommen lassen, werden Ihre Angaben aus dem Anfrageformular inklusive der von Ihnen dort angegebenen Kontaktdaten zwecks Bearbeitung der Anfrage und für den Fall von Anschlussfragen bei uns gespeichert. Diese Daten geben wir nicht ohne Ihre Einwilligung weiter.`),Fu(),Bi(117,`p`),Lb(118,`Die Verarbeitung der in das Kontaktformular eingegebenen Daten erfolgt somit ausschließlich auf Grundlage Ihrer Einwilligung (Art. 6 Abs. 1 lit. a DSGVO). Sie können diese Einwilligung jederzeit widerrufen. Dazu reicht eine formlose Mitteilung per E-Mail an uns. Die Rechtmäßigkeit der bis zum Widerruf erfolgten Datenverarbeitungsvorgänge bleibt vom Widerruf unberührt.`),Fu(),Bi(119,`p`),Lb(120,`Die von Ihnen im Kontaktformular eingegebenen Daten verbleiben bei uns, bis Sie uns zur Löschung auffordern, Ihre Einwilligung zur Speicherung widerrufen oder der Zweck für die Datenspeicherung entfällt (z.B. nach abgeschlossener Bearbeitung Ihrer Anfrage). Zwingende gesetzliche Bestimmungen – insbesondere Aufbewahrungsfristen – bleiben unberührt.`),Fu(),Bi(121,`h2`),Lb(122,`4. Plugins und Tools`),Fu(),Bi(123,`h3`),Lb(124,`YouTube`),Fu(),Bi(125,`p`),Lb(126,`Unsere Website nutzt Plugins der von Google betriebenen Seite YouTube. Betreiber der Seiten ist die YouTube, LLC, 901 Cherry Ave., San Bruno, CA 94066, USA.`),Fu(),Bi(127,`p`),Lb(128,`Wenn Sie eine unserer mit einem YouTube-Plugin ausgestatteten Seiten besuchen, wird eine Verbindung zu den Servern von YouTube hergestellt. Dabei wird dem YouTube-Server mitgeteilt, welche unserer Seiten Sie besucht haben.`),Fu(),Bi(129,`p`),Lb(130,`Wenn Sie in Ihrem YouTube-Account eingeloggt sind, ermöglichen Sie YouTube, Ihr Surfverhalten direkt Ihrem persönlichen Profil zuzuordnen. Dies können Sie verhindern, indem Sie sich aus Ihrem YouTube-Account ausloggen.`),Fu(),Bi(131,`p`),Lb(132,`Die Nutzung von YouTube erfolgt im Interesse einer ansprechenden Darstellung unserer Online-Angebote. Dies stellt ein berechtigtes Interesse im Sinne von Art. 6 Abs. 1 lit. f DSGVO dar.`),Fu(),Bi(133,`p`),Lb(134,`Weitere Informationen zum Umgang mit Nutzerdaten finden Sie in der Datenschutzerklärung von YouTube unter: `),Bi(135,`a`,8),Lb(136,`https://www.google.de/intl/de/policies/privacy`),Fu(),Lb(137,`.`),Fu()()()()()()())},dependencies:[x,_r],styles:[`a[_ngcontent-%COMP%]{text-decoration:underline}a[_ngcontent-%COMP%]:hover{text-decoration:none}h3[_ngcontent-%COMP%]{font-size:1.5rem}`]})};export{d as PrivacyPage};